import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import path from "node:path";
import { mergeContractManifest } from "../../../scripts/merge-drivers/contract-manifest-merge";
import { serializeContractManifest } from "../../../scripts/generate-contract-manifest";

// Any two branches that add a command both change counts.commands, so the
// committed manifest conflicted on every merge and was regenerated by hand.

type Manifest = Parameters<typeof serializeContractManifest>[0];

function command(domain: string, digest: string) {
  return {
    domain,
    since: 1,
    access: "internal",
    read: false,
    critical: [],
    argsDigest: `sha256:${digest}`,
    resultDigest: `sha256:${digest}`,
  };
}

function manifest(
  commands: Record<string, unknown>,
  options: { events?: Record<string, unknown>; domains?: Record<string, unknown> } = {},
): string {
  const values = Object.values(commands) as Array<{ untyped?: boolean; domain: string }>;
  const untypedByDomain: Record<string, number> = {};
  for (const entry of values) {
    if (entry.untyped) untypedByDomain[entry.domain] = (untypedByDomain[entry.domain] ?? 0) + 1;
  }
  const untyped = Object.values(untypedByDomain).reduce((a, b) => a + b, 0);
  const events = options.events ?? { "a-changed": { domain: "a", payloadDigest: "sha256:e" } };
  const sortedKeys = (record: Record<string, unknown>) =>
    Object.fromEntries(
      Object.keys(record)
        .sort()
        .map((key) => [key, record[key]]),
    );
  return serializeContractManifest({
    schemaVersion: 1,
    generatedBy: "scripts/generate-contract-manifest.ts (mise run contract:manifest)",
    counts: {
      commands: values.length,
      defined: values.length - untyped,
      untyped,
      events: Object.keys(events).length,
    },
    untypedByDomain: sortedKeys(untypedByDomain),
    domains: sortedKeys(options.domains ?? { a: { version: 1, min: 1 } }),
    commands: sortedKeys(commands),
    events: sortedKeys(events),
  } as unknown as Manifest);
}

const base = manifest({ alpha: command("a", "1"), gamma: command("a", "3") });

describe("mergeContractManifest", () => {
  test("keeps commands both sides added and recomputes the totals", () => {
    const ours = manifest({
      alpha: command("a", "1"),
      beta: command("a", "2"),
      gamma: command("a", "3"),
    });
    const theirs = manifest({
      alpha: command("a", "1"),
      delta: { domain: "b", untyped: true, read: true },
      gamma: command("a", "3"),
    });

    expect(mergeContractManifest(base, ours, theirs)).toBe(
      manifest({
        alpha: command("a", "1"),
        beta: command("a", "2"),
        delta: { domain: "b", untyped: true, read: true },
        gamma: command("a", "3"),
      }),
    );
  });

  test("takes one side's change to an entry and the other's removal", () => {
    const ours = manifest({ alpha: command("a", "changed"), gamma: command("a", "3") });
    const theirs = manifest(
      { alpha: command("a", "1") },
      { domains: { a: { version: 2, min: 1 } } },
    );

    expect(mergeContractManifest(base, ours, theirs)).toBe(
      manifest({ alpha: command("a", "changed") }, { domains: { a: { version: 2, min: 1 } } }),
    );
  });

  test("the same domain bump on both sides is not a conflict", () => {
    const bumped = { domains: { a: { version: 2, min: 1 } } };
    const ours = manifest(
      { alpha: command("a", "1"), beta: command("a", "2"), gamma: command("a", "3") },
      bumped,
    );
    const theirs = manifest(
      { alpha: command("a", "1"), gamma: command("a", "3"), zeta: command("a", "9") },
      bumped,
    );

    expect(JSON.parse(mergeContractManifest(base, ours, theirs)!).domains).toEqual(bumped.domains);
  });

  test("refuses an entry both sides changed differently", () => {
    const ours = manifest({ alpha: command("a", "ours"), gamma: command("a", "3") });
    const theirs = manifest({ alpha: command("a", "theirs"), gamma: command("a", "3") });
    expect(mergeContractManifest(base, ours, theirs)).toBeNull();
  });

  test("refuses unreadable or unknown shapes", () => {
    expect(mergeContractManifest(base, "{", base)).toBeNull();
    const extra = JSON.stringify({ ...JSON.parse(base), surprise: true });
    expect(mergeContractManifest(base, extra, base)).toBeNull();
  });

  test("merging the committed manifest with itself reproduces it byte for byte", () => {
    const committed = readFileSync(
      path.resolve(import.meta.dir, "../../../packages/protocol/contracts/manifest.json"),
      "utf8",
    );
    expect(mergeContractManifest(committed, committed, committed)).toBe(committed);
  });
});
